mapper.select:
select
a.task_id,
a.task_name,
a.plan_id,
a.area_id,
a.type,
a.if_run,
a.robot_id,
a.date_type,
a.task_type,
a.start_time,
a.create_time
from t_cruise_task a
where 1 = 1
 and a.task_id = #{taskId, jdbcType=VARCHAR}
 and a.task_name = #{taskName, jdbcType=VARCHAR}
 and a.plan_id = #{planId, jdbcType=BIGINT}
 and a.area_id = #{areaId, jdbcType=VARCHAR}
 and a.type = #{type, jdbcType=INTEGER}
 and a.if_run = #{ifRun, jdbcType=INTEGER}
 and a.robot_id = #{robotId, jdbcType=BIGINT}
 and a.date_type = #{dateType, jdbcType=VARCHAR}
 and a.task_type = #{taskType, jdbcType=INTEGER}
 and a.start_time = #{startTime, jdbcType=TIMESTAMP}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}

